from collections import *
from random import *
for _ in range(int(input())):
	n = int(input())
	a = [int(x) for x in input().split()]
	d = defaultdict(int)
	for i in a:
		d[i] += 1
	b = []
	for (key, value) in d.items():
		if value % 2 == 1:
			b.append(key)
	count = 0
	for i in b:
		count = count ^ i
	if count == 0 or len(b) % 2 == 0:
		print('First')
	else:
		print('Second')
